mapper.select:
SELECT g.id, g.sid, g.semester_id, g.conclusion, g.detail_json, g.auditor_uid, g.audit_time, st.name AS student_name, sem.name AS semester_name, a.username AS auditor_name FROM graduate_audit g LEFT JOIN student st ON st.sid = g.sid LEFT JOIN semester sem ON sem.id = g.semester_id LEFT JOIN admin a ON a.uid = g.auditor_uid
AND g.sid = #{sid}
ORDER BY g.audit_time DESC, g.id DESC
